#include <vector>

class Solution {
public:
    int peakValleyDifference(std::vector<int>& nums) {
        long long peaks = 0, valleys = 0;
        for (int i = 1; i < (int)nums.size() - 1; ++i) {
            if (nums[i] > nums[i - 1] && nums[i] > nums[i + 1]) peaks += nums[i];
            else if (nums[i] < nums[i - 1] && nums[i] < nums[i + 1]) valleys += nums[i];
        }
        return peaks - valleys;
    }
};

class Solution {
    public int countPeaksAndValleys(int[] nums) {
        int n = nums.length;
        if (n < 3) return 0;
        int count = 0;
        for (int i = 1; i < n - 1; i++) {
            if ((nums[i] > nums[i - 1] && nums[i] > nums[i + 1]) ||
                (nums[i] < nums[i - 1] && nums[i] < nums[i + 1])) {
                count++;
            }
        }
        return count;
    }
}

